#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdbool.h>

int main() {
    int n;
    if (scanf("%d", &n) != 1) return 0;
    long long max_so_far = -1000000000000000LL, curr = 0;
    for (int i = 0; i < n; i++) {
        long long val;
        scanf("%lld", &val);
        if (i == 0) {
            max_so_far = val;
            curr = val;
        } else {
            curr = (val > curr + val) ? val : curr + val;
            if (curr > max_so_far) max_so_far = curr;
        }
    }
    printf("%lld\n", max_so_far);
    return 0;
}

